    """Build every window and adjacent segment on one frozen view.

    Shared by :meth:`lifetime_evolution`, :meth:`lifetime_churn`,
    :meth:`lifetime_churn_streaks` and :meth:`lifetime_churn_waves`
    so all run the same state checks, caps and token reserve/refund
    semantics over one identical window batch. ``result_kind``
    selects the assembled shape: ``"evolution"`` returns the
    ``windows``/``segments`` dict and ignores every extra limit;
    ``"churn"`` returns the aggregated ``identities``/``totals``
    dict, enforcing ``churn_limit_value`` only after every full
    record set is known; ``"streaks"`` returns the
    ``streaks``/``totals`` dict built from the same changes,
    enforcing ``streak_limit_value`` only once every complete streak
    is known; ``"waves"`` returns the ``waves``/``totals`` dict of
    the consecutive-segment runs where at least
    ``min_identities_value`` distinct identities churn per segment,
    enforcing ``wave_limit_value`` only once every complete wave is
    known.
    """
    # Token checks come after every ordinary parameter. Without a token
    # the query runs on live state exactly as before; with one, the read
    # allowance is reserved atomically before any state check and given
    # back if a state check (KeyError/ValueError below) fails, so only
    # fully successful queries consume a read. Every window is then
    # answered from the token's one frozen view.
    view = self
    if token is not None:
        view = self._reserve_snapshot_read(token)
    try:
        # Capture the single read-only historical view once; every
        # window selects its snapshots and adjacent segments from it,
        # so the batch never reads different branch states per window.
        prepared = view._capture_frontier_view(validated)

        window_records: list[tuple[dict[str, object], ...]] = []
        for position, index_values in enumerate(index_windows):
            snapshots, segments = view._cascade_slice_timeline_data(
                prepared,
                index_values,
                causes,
                direction,
                depth_value,
                node_limit_value,
                change_limit_value,
            )
            lifetimes = view._build_slice_lifetimes(snapshots, segments)
            if len(lifetimes) > lifetime_limit_value:
                raise ValueError(
                    f"lifetime {result_kind} lifetime limit exceeded: "
                    f"{len(lifetimes)} lifetime records on window at "
                    f"position {position}, limit is "
                    f"{lifetime_limit_value}"
                )
            window_records.append(lifetimes)

        # Every segment's full change set is known before either cap is
        # enforced, so an over-cap batch returns no partial result.
        segment_changes: list[tuple[dict[str, object], ...]] = []
        total_changes = 0
        for position in range(len(window_records) - 1):
            changes = view._build_lifetime_changes(
                window_records[position], window_records[position + 1]
            )
            if len(changes) > diff_limit_value:
                raise ValueError(
                    f"lifetime {result_kind} diff limit exceeded: "
                    f"{len(changes)} change records on segment between "
                    f"windows at positions {position} and {position + 1}, "
                    f"limit is {diff_limit_value}"
                )
            total_changes += len(changes)
            segment_changes.append(changes)
        if total_changes > total_diff_limit_value:
            raise ValueError(
                f"lifetime {result_kind} total diff limit exceeded: "
                f"{total_changes} change records over "
                f"{len(segment_changes)} segment(s), limit is "
                f"{total_diff_limit_value}"
            )

        if result_kind == "churn":
            result = view._build_lifetime_churn_result(
                window_records, segment_changes, churn_limit_value
            )
        elif result_kind == "streaks":
            result = view._build_lifetime_churn_streaks_result(
                segment_changes, streak_limit_value
            )
        elif result_kind == "waves":
            result = view._build_lifetime_churn_waves_result(
                segment_changes, min_identities_value, wave_limit_value
            )
        else:
            result = {
                "windows": tuple(
                    {
                        "position": position,
                        "lifetimes": tuple(
                            view._copy_lifetime_record(record)
                            for record in lifetimes
                        ),
                    }
                    for position, lifetimes in enumerate(window_records)
                ),
                "segments": tuple(
                    {
                        "left": position,
                        "right": position + 1,
                        "changes": changes,
                    }
                    for position, changes in enumerate(segment_changes)
                ),
            }
    except BaseException:
        if token is not None:
            self._refund_snapshot_read(token)
        raise
    return result

@staticmethod
def _freeze_lifetime_value(value: object) -> object:
    """Return an isolated tuple/dict-only copy of a lifetime value."""
    if isinstance(value, dict):
        return {
            key: BranchStore._freeze_lifetime_value(item)
            for key, item in value.items()
        }
    if isinstance(value, (tuple, list)):
        return tuple(
            BranchStore._freeze_lifetime_value(item) for item in value
        )
    return value

@staticmethod
def _copy_lifetime_record(record: dict[str, object]) -> dict[str, object]:
    """Return an isolated copy of one lifetime record.

    The copy keeps the existing key order -- ``type, identity,
    first_seen, last_seen, intervals, transitions`` -- and shares no
    mutable object with the source record.
    """
    return {
        "type": record["type"],
        "identity": BranchStore._freeze_lifetime_value(
            record["identity"]
        ),
        "first_seen": record["first_seen"],
        "last_seen": record["last_seen"],
        "intervals": tuple(
            tuple(interval) for interval in record["intervals"]
        ),
        "transitions": tuple(
            {
                "kind": transition["kind"],
                "before": BranchStore._freeze_lifetime_value(
                    transition["before"]
                ),
                "after": BranchStore._freeze_lifetime_value(
                    transition["after"]
                ),
            }
            for transition in record["transitions"]
        ),
    }

@staticmethod
def _build_lifetime_churn_result(
    window_records: list[tuple[dict[str, object], ...]],
    segment_changes: list[tuple[dict[str, object], ...]],
    churn_limit_value: int | None,
) -> dict[str, object]:
    """Aggregate per-identity churn over every window and segment.

    Used only by :meth:`lifetime_churn`. Every node, edge and gap
    identity present in any window or touched by any adjacent
    segment gets one fresh record carrying the window positions it
    exists in, its addition/removal/change counters and, in segment
    order, one isolated ``from, to, kind, before, after`` entry per
    segment change. Records are visited deterministically -- windows
    in position order, each window in its node/edge/gap lifetime
    order, then change-only identities as the segments run -- and
    sorted by the counter sum descending, then the first presence
    position ascending (a change-only identity uses its first
    change's ``to``), then the existing type grouping and identity
    encounter order. The complete record set is built before the
    ``churn_limit`` cap is enforced, so an over-limit query raises
    :class:`ValueError` without returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}
    present: dict[tuple[str, object], list[int]] = {}
    encounter: dict[tuple[str, object], int] = {}
    next_encounter = 0
    for position, lifetimes in enumerate(window_records):
        for record in lifetimes:
            key = (record["type"], record["identity"])
            if key not in present:
                present[key] = []
                encounter[key] = next_encounter
                next_encounter += 1
            present[key].append(position)

    added: dict[tuple[str, object], int] = {}
    removed: dict[tuple[str, object], int] = {}
    changed: dict[tuple[str, object], int] = {}
    identity_changes: dict[
        tuple[str, object], list[dict[str, object]]
    ] = {}
    first_change_to: dict[tuple[str, object], int] = {}
    for position, changes in enumerate(segment_changes):
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            key = (type_name, change["identity"])
            if key not in encounter:
                encounter[key] = next_encounter
                next_encounter += 1
                first_change_to[key] = position + 1
            if change["kind"].endswith("_added"):
                added[key] = added.get(key, 0) + 1
            elif change["kind"].endswith("_removed"):
                removed[key] = removed.get(key, 0) + 1
            else:
                changed[key] = changed.get(key, 0) + 1
            before = change["before"]
            after = change["after"]
            identity_changes.setdefault(key, []).append(
                {
                    "from": position,
                    "to": position + 1,
                    "kind": change["kind"],
                    "before": (
                        None
                        if before is None
                        else BranchStore._copy_lifetime_record(before)
                    ),
                    "after": (
                        None
                        if after is None
                        else BranchStore._copy_lifetime_record(after)
                    ),
                }
            )

    ordered_keys = sorted(
        encounter,
        key=lambda key: (
            -(
                added.get(key, 0)
                + removed.get(key, 0)
                + changed.get(key, 0)
            ),
            present[key][0] if key in present else first_change_to[key],
            type_order[key[0]],
            encounter[key],
        ),
    )
    if len(ordered_keys) > churn_limit_value:
        raise ValueError(
            f"lifetime churn limit exceeded: {len(ordered_keys)} "
            f"identity records, limit is {churn_limit_value}"
        )

    total_added = 0
    total_removed = 0
    total_changed = 0
    records: list[dict[str, object]] = []
    for key in ordered_keys:
        type_name, identity = key
        added_count = added.get(key, 0)
        removed_count = removed.get(key, 0)
        changed_count = changed.get(key, 0)
        total_added += added_count
        total_removed += removed_count
        total_changed += changed_count
        records.append(
            {
                "type": type_name,
                "identity": BranchStore._freeze_lifetime_value(identity),
                "present": tuple(present.get(key, ())),
                "added": added_count,
                "removed": removed_count,
                "changed": changed_count,
                "changes": tuple(identity_changes.get(key, ())),
            }
        )
    return {
        "identities": tuple(records),
        "totals": {
            "identities": len(records),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

@staticmethod
def _build_lifetime_churn_streaks_result(
    segment_changes: list[tuple[dict[str, object], ...]],
    streak_limit_value: int | None,
) -> dict[str, object]:
    """Group each identity's churn into consecutive-segment streaks.

    Used only by :meth:`lifetime_churn_streaks`. Every node, edge and
    gap identity touched by an adjacent segment is followed across the
    segments in order; one change (added, removed or changed) on each
    of consecutive segments extends the same streak, while a segment
    without a change for that identity cuts it. A single changed
    segment is a streak on its own, so an identity present but
    unchanged in the first window never appears; being removed on one
    segment and re-added on the next stays one continuous streak.

    Identities keep the deterministic encounter order in which the
    segments' changes first name them. Each streak gets one fresh
    record with ordered keys ``type, identity, from, to, segments,
    added, removed, changed, changes``; ``from``/``to`` are the left
    window position of the streak's first segment and the right
    window position of its last, and ``changes`` keeps one isolated
    ``from, to, kind, before, after`` entry per segment. Records sort
    by total change count descending, then ``from`` and ``to``
    ascending, then the node, edge, gap grouping and identity
    encounter order. The complete set is built before the

    ``streak_limit`` cap is enforced, so an over-limit query raises
    :class:`ValueError` without returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}
    # Key -> ordered list of (segment position, change) it appears in.
    per_identity: dict[
        tuple[str, object], list[tuple[int, dict[str, object]]]
    ] = {}
    encounter: dict[tuple[str, object], int] = {}
    next_encounter = 0
    for position, changes in enumerate(segment_changes):
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            key = (type_name, change["identity"])
            if key not in encounter:
                encounter[key] = next_encounter
                next_encounter += 1
            per_identity.setdefault(key, []).append((position, change))

    records: list[dict[str, object]] = []
    for key, entries in per_identity.items():
        type_name, identity = key
        run: list[tuple[int, dict[str, object]]] = []

        def flush(run_entries: list[tuple[int, dict[str, object]]]) -> None:
            added_count = 0
            removed_count = 0
            changed_count = 0
            evidence: list[dict[str, object]] = []
            for run_position, change in run_entries:
                kind = change["kind"]
                if kind.endswith("_added"):
                    added_count += 1
                elif kind.endswith("_removed"):
                    removed_count += 1
                else:
                    changed_count += 1
                before = change["before"]
                after = change["after"]
                evidence.append(
                    {
                        "from": run_position,
                        "to": run_position + 1,
                        "kind": kind,
                        "before": (
                            None
                            if before is None
                            else BranchStore._copy_lifetime_record(before)
                        ),
                        "after": (
                            None
                            if after is None
                            else BranchStore._copy_lifetime_record(after)
                        ),
                    }
                )
            records.append(
                {
                    "type": type_name,
                    "identity": BranchStore._freeze_lifetime_value(
                        identity
                    ),
                    "from": run_entries[0][0],
                    "to": run_entries[-1][0] + 1,
                    "segments": len(run_entries),
                    "added": added_count,
                    "removed": removed_count,
                    "changed": changed_count,
                    "changes": tuple(evidence),
                }
            )

        for entry in entries:
            if run and entry[0] != run[-1][0] + 1:
                flush(run)
                run = []
            run.append(entry)
        if run:
            flush(run)

    records.sort(
        key=lambda record: (
            -(
                record["added"]
                + record["removed"]
                + record["changed"]
            ),
            record["from"],
            record["to"],
            type_order[record["type"]],
            encounter[(record["type"], record["identity"])],
        )
    )
    if len(records) > streak_limit_value:
        raise ValueError(
            f"lifetime churn streak limit exceeded: {len(records)} "
            f"streak records, limit is {streak_limit_value}"
        )

    total_added = 0
    total_removed = 0
    total_changed = 0
    for record in records:
        total_added += record["added"]
        total_removed += record["removed"]
        total_changed += record["changed"]
    return {
        "streaks": tuple(records),
        "totals": {
            "streaks": len(records),
            "identities": len(per_identity),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

@staticmethod
def _build_lifetime_churn_waves_result(
    segment_changes: list[tuple[dict[str, object], ...]],
    min_identities_value: int,
    wave_limit_value: int | None,
) -> dict[str, object]:
    """Group multi-identity churn into consecutive-segment waves.

    Used only by :meth:`lifetime_churn_waves`. A segment qualifies
    when at least ``min_identities_value`` distinct node, edge or
    gap identities carry an ``added``, ``removed`` or ``changed``
    record on it -- one identity appearing several times on the same
    segment still counts once toward the threshold, while every
    change record feeds the counters. Each maximal run of
    consecutive qualifying segments forms one wave; a segment below
    the threshold cuts the run and the next qualifying segment
    starts a new wave.

    Every wave gets one fresh record with ordered keys ``from, to,
    segments, identities, added, removed, changed, members,
    changes``; ``from``/``to`` are the left window position of the
    run's first segment and the right window position of its last,
    ``members`` keeps one fresh ``type, identity, segments, added,
    removed, changed`` record per distinct identity sorted by
    segment count and total change count descending, then the
    identity's first segment in the wave ascending, then the node,
    edge, gap grouping and the wave's deterministic encounter order,
    and ``changes`` keeps one isolated ``from, to, kind, before,
    after`` entry per change record in segment and original change
    order. Waves sort by ``from`` then ``to`` ascending. The
    complete set is built before the ``wave_limit`` cap is enforced,
    so an over-limit query raises :class:`ValueError` without
    truncating or returning partial records.
    """
    type_order = {"node": 0, "edge": 1, "gap": 2}

    # A segment qualifies when its distinct churning identities
    # reach min_identities_value; qualifying runs of consecutive
    # segments become the waves.
    runs: list[list[int]] = []
    run: list[int] = []
    for position, changes in enumerate(segment_changes):
        distinct: dict[tuple[str, object], None] = {}
        for change in changes:
            type_name = change["kind"].split("_", 1)[0]
            distinct[(type_name, change["identity"])] = None
        if len(distinct) >= min_identities_value:
            run.append(position)
        elif run:
            runs.append(run)
            run = []
    if run:
        runs.append(run)

    waves: list[dict[str, object]] = []
    all_identities: dict[tuple[str, object], None] = {}
    total_added = 0
    total_removed = 0
    total_changed = 0
    for run_positions in runs:
        encounter: dict[tuple[str, object], int] = {}
        first_segment: dict[tuple[str, object], int] = {}
        member_segments: dict[tuple[str, object], set[int]] = {}
        member_added: dict[tuple[str, object], int] = {}
        member_removed: dict[tuple[str, object], int] = {}
        member_changed: dict[tuple[str, object], int] = {}
        evidence: list[dict[str, object]] = []
        for position in run_positions:
            for change in segment_changes[position]:
                type_name = change["kind"].split("_", 1)[0]
                key = (type_name, change["identity"])
                if key not in encounter:
                    encounter[key] = len(encounter)
                    first_segment[key] = position
                    member_segments[key] = set()
                    member_added[key] = 0
                    member_removed[key] = 0
                    member_changed[key] = 0
                    all_identities[key] = None
                member_segments[key].add(position)
                kind = change["kind"]
                if kind.endswith("_added"):
                    member_added[key] += 1
                elif kind.endswith("_removed"):
                    member_removed[key] += 1
                else:
                    member_changed[key] += 1
                before = change["before"]
                after = change["after"]
                evidence.append(
                    {
                        "from": position,
                        "to": position + 1,
                        "kind": kind,
                        "before": (
                            None
                            if before is None
                            else BranchStore._copy_lifetime_record(before)
                        ),
                        "after": (
                            None
                            if after is None
                            else BranchStore._copy_lifetime_record(after)
                        ),
                    }
                )

        ordered_keys = sorted(
            encounter,
            key=lambda key: (
                -len(member_segments[key]),
                -(
                    member_added[key]
                    + member_removed[key]
                    + member_changed[key]
                ),
                first_segment[key],
                type_order[key[0]],
                encounter[key],
            ),
        )
        members = tuple(
            {
                "type": key[0],
                "identity": BranchStore._freeze_lifetime_value(key[1]),
                "segments": len(member_segments[key]),
                "added": member_added[key],
                "removed": member_removed[key],
                "changed": member_changed[key],
            }
            for key in ordered_keys
        )
        wave_added = sum(member_added.values())
        wave_removed = sum(member_removed.values())
        wave_changed = sum(member_changed.values())
        total_added += wave_added
        total_removed += wave_removed
        total_changed += wave_changed
        waves.append(
            {
                "from": run_positions[0],
                "to": run_positions[-1] + 1,
                "segments": len(run_positions),
                "identities": len(members),
                "added": wave_added,
                "removed": wave_removed,
                "changed": wave_changed,
                "members": members,
                "changes": tuple(evidence),
            }
        )

    waves.sort(key=lambda wave: (wave["from"], wave["to"]))
    if len(waves) > wave_limit_value:
        raise ValueError(
            f"lifetime churn wave limit exceeded: {len(waves)} "
            f"wave records, limit is {wave_limit_value}"
        )
    return {
        "waves": tuple(waves),
        "totals": {
            "waves": len(waves),
            "identities": len(all_identities),
            "added": total_added,
            "removed": total_removed,
            "changed": total_changed,
        },
    }

@staticmethod
def _build_lifetime_changes(
    left_lifetimes: tuple[dict[str, object], ...],
    right_lifetimes: tuple[dict[str, object], ...],
) -> tuple[dict[str, object], ...]:
    """Compare two windows' lifetime records type by type, by identity.

    Records are grouped by nodes, then edges, then gaps; each group
    runs removed, added and changed. Removed and changed records
    follow the left window's identity order, added records the right
    window's, so the output is stable. An identity present in both
    windows changes when its first/last position, presence intervals
    or classification transitions differ; a completely equal pair is
    omitted. Every present side is copied again, so the change
    records share no object with either returned lifetime tuple.
    """
    changes: list[dict[str, object]] = []
    for type_name in ("node", "edge", "gap"):
        left_records = [
            record
            for record in left_lifetimes
            if record["type"] == type_name
        ]
        right_records = [
            record
            for record in right_lifetimes
            if record["type"] == type_name
        ]
        left_by_identity = {
            record["identity"]: record for record in left_records
        }
        right_by_identity = {
            record["identity"]: record for record in right_records
        }
        for record in left_records:
            if record["identity"] not in right_by_identity:
                changes.append(
                    {
                        "kind": f"{type_name}_removed",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": BranchStore._copy_lifetime_record(
                            record
                        ),
                        "after": None,
                    }
                )
        for record in right_records:
            if record["identity"] not in left_by_identity:
                changes.append(
                    {
                        "kind": f"{type_name}_added",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": None,
                        "after": BranchStore._copy_lifetime_record(
                            record
                        ),
                    }
                )
        for record in left_records:
            other = right_by_identity.get(record["identity"])
            if other is None:
                continue
            changed = (
                record["first_seen"] != other["first_seen"]
                or record["last_seen"] != other["last_seen"]
                or record["intervals"] != other["intervals"]
                or record["transitions"] != other["transitions"]
            )
            if changed:
                changes.append(
                    {
                        "kind": f"{type_name}_changed",
                        "identity": BranchStore._freeze_lifetime_value(
                            record["identity"]
                        ),
                        "before": BranchStore._copy_lifetime_record(
                            record
                        ),
                        "after": BranchStore._copy_lifetime_record(
                            other
                        ),
                    }
                )
    return tuple(changes)

def _cascade_slice_timeline_data(
